"""単独Short5本(歴史の逸話)：塩(shio)・人間五十年(atsumori)・是非に及ばず(zehi)・人は城(hito_shiro)・厳島の兵力(itsukushima)。
根拠はすべて日本語版Wikipedia(2026年11月7日に取得)。原文で読めた部分だけを台本に使い、要約でしか確認できなかった内容は使っていない。各書の原本は読めていない。
背景はFreeVideo(動き多め・7秒)、図は自作。nolong, nolink。"""
import json
from pathlib import Path
R = Path(__file__).resolve().parents[1]
IDS = json.loads((R / 'data' / 'youtube_ids.json').read_text(encoding='utf8'))
BG = '・背景映像：FreeVideo(MiniMax H3)によるAI生成映像。イメージです。実際の風景・史実の再現ではありません\n・図・表：自作'
NOTE_TAIL = '・動画内の図(年表・比較)は自作です。背景の映像は FreeVideo(MiniMax H3)によるAI生成で、イメージです。実際の風景・史実の再現ではありません。\n'


def mk(slug, title, head, hook, answer, notes, pron, scenes):
    (R / 'data' / f'{slug}_pron.json').write_text(json.dumps(pron, ensure_ascii=False), encoding='utf8')
    V = lambda n: f'assets/{slug}/fv/clip{n}.mp4'
    sc = []
    for i, s in enumerate(scenes):
        d = dict(text=s['text'], big=s['big'].replace('、', ''), sub=s['sub'].replace('、', ''), src=s['src'], vid=V(i + 1), dim=0.7, viz=s['viz'])
        if i:
            d['col'] = 'white'
        sc.append(d)
    sc.append(dict(text='', end=True, vid=V(1), dim=0.7))
    o = dict(title=title, head=head, pron=f'data/{slug}_pron.json', art='assets/tohoku/bg_one.png', hook=hook, notes=notes + NOTE_TAIL, answer=answer,
             credit=BG, suffix='整理', nolong=True, nolink=True, long_id=IDS['43_bukka']['video_id'], long_title='43_bukka', scenes=sc)
    (R / 'data' / f'short_solo_{slug}.json').write_text(json.dumps(o, ensure_ascii=False, indent=1), encoding='utf8')
    print('ok', slug)


def T(gap, ev):
    return dict(type='timeline', gap=gap, events=ev)


